    'gd.sample.d': '٤٢٠ طالب وهمي، و٢٤ مجموعة، و٨ أسابيع حضور وفلوس، علشان تشوف كل صفحة بتشتغل إزاي قبل بياناتك الحقيقية.',
    'gd.sample.1': 'افتح «الإعدادات»، واختار [[set.tab.data]].',
