    'gd.sample.3': 'اقرا الرسالة، واضغط [[sample.load]] تاني للتأكيد. استنى حوالي ١٠ ثواني لحد ما تظهر رسالة «اتحفظ» الخضرا.',
    'gd.sample.4': 'افتح صفحة «الطلاب»: هتلاقي ٤٢٠ طالب بصفوفهم ومجموعاتهم وحساباتهم. النقطة الحمرا معناها «محتاج متابعة»، والرقم بالسالب معناه إن على الطالب فلوس.',
    'gd.sample.5': 'افتح الاستقبال، واكتب 10007 في خانة البحث، وهتشوف كارت الطالب والمصاريف وزرار تسجيل الحضور. اتمرّن على باقي الأدلة هنا براحتك، مفيش حاجة حقيقية.',
