    'gd.sample.7': 'لما تكون جاهز للشغل الحقيقي: «الإعدادات» ثم [[set.tab.data]] ثم [[sample.delete]]، وبعدين أكّد.',
    'gd.sample.8': 'كل طلاب ومجموعات وإيصالات وحسابات التجربة هتتشال (هتروح سلة المحذوفات، يعني حتى دي ممكن ترجّعها). والحاجات اللي انت دخّلتها بنفسك هتفضل زي ما هي.',
