    'sit.theft.q': 'شاكك إن حد في الاستقبال بياخد فلوس',
    'sit.theft.a': 'ماتتهمش حد، راقب بهدوء. صفحة «الرقابة» بتوريك: الإيصالات اللي اتلغت واتعمل بعدها إيصال بمبلغ أقل، والأدراج اللي بتتقفل ناقصة أكتر من مرة، والطلاب اللي بيحضروا من غير ما يدفعوا. افتح سجل النشاط ثم [[act.tab.clicks]] لنفس اليوم، وهتشوف مين ضغط على إيه وإمتى. وبعدين كلّم اتنين أو تلاتة أولياء أمور واسألهم دفعوا كام ورقم الإيصال اللي معاهم. لو فيه إيصال ورق برقم مش موجود في البرنامج، ده دليل واضح.',
    'sit.cashNoReceipt.q': 'ولي أمر بيقول إنه دفع ومخدش إيصال',
    'sit.cashNoReceipt.a': 'الفلوس اللي بتتاخد من غير إيصال هي أصعب حاجة تتكشف، فخليها قاعدة الكل عارفها: «مفيش إيصال يعني مفيش دفع». حط ورقة واضحة على المكتب بالكلام ده. وراجع في «الرقابة» الأدراج اللي بتتقفل فيها زيادة (فلوس من غير إيصال)، والطلاب اللي بيحضروا من غير دفع. الإيصالات مترقّمة بالترتيب على كل جهاز، فمستحيل رقم يختفي من غير ما يبان.',
    'sit.staffAccount.q': 'الموظفين كلهم بيستخدموا نفس كلمة السر',
    'sit.staffAccount.a': 'كده مش هتعرف مين عمل إيه. ادّي كل واحد حساب خاص بيه ([[acc.add]]) بالصلاحيات اللي محتاجها بس، وقوله إن كل حاجة بيعملها بتتسجّل باسمه. وخلّي صلاحيات [[perm.money.void]] و[[perm.students.discount]] و[[perm.attendance.edit]] معاك انت أو مع مدير تثق فيه.',
